#define R(a) mat2(cos(a),sin(a),-sin(a),cos(a)) // rot

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int aa = int(texelFetch(iChannel1, ivec2(5,0), 0 ).x);
    vec2 ppos = texelFetch(iChannel1, ivec2(10,0), 0 ).xy;
    int zoom = int(texelFetch(iChannel1, ivec2(14,0), 0 ).x);

    float mx= iMouse.x / iResolution.x;

    if (zoom == 1) {
        mx= (sin((iTime-5.) * 0.4) * iResolution.x /2.3 + iResolution.x / 2.3) / iResolution.x;
        ppos = vec2(0.);
    } else if (zoom == 2) {
        fragCoord = (fragCoord-iResolution.xy*0.5) * R(iTime*0.5) + iResolution.xy * 0.5;
        mx= (sin((iTime-5.) * 0.4) * iResolution.x /5. + iResolution.x / 5.) / iResolution.x;
        mx = clamp(mx + 1. - min(iResolution.x,iResolution.y) / max(iResolution.x,iResolution.y) + 0.056, 0.0, 0.99);    }

    vec2 mid = iResolution.xy / 2.;
    float mmul = 1.-mx;
    fragCoord = mid - (mid*mmul-fragCoord*mmul) + ppos;

    vec4 val = texelFetch( iChannel0, ivec2(fragCoord), 0 );
    if (aa == 0 || aa == 2)
        fragColor = val * val * (aa==0 ? 1. : 2.5);
    else
        fragColor = val * (aa==1 ? 1.15 : 1.45);
}

int cell( in ivec2 p )
{
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p+r) % r;
    float val = texelFetch(iChannel0, p, 0 ).w;
    return ( int(val) == sstarget ) ? 1 : 0;
}
vec4 cellval( in ivec2 p )
{
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p+r) % r;
    return texelFetch(iChannel0, p, 0 );
}
int cellbl( in ivec2 p )
{
    ivec2 r = ivec2(textureSize(iChannel0, 0));
    p = (p+r) % r;
    float val = texelFetch(iChannel0, p, 0 ).w;
    return ( int(val) == 0 || int(val) > int(liveval-2.) ) ? 0 : 1;
}

float randpix(vec2 fragCoord) {
    float rn = hash1(iTime+fragCoord.x*13.0+hash1(fragCoord.y*37.1));
    //if (rn * 100. > density) return 0.;
    return floor(mod(rn * 10000., liveval + 1.));
}

float restart(vec2 fragCoord, int method) {
    if (method == 0)
        return randpix(fragCoord);

    vec2 mid = iResolution.xy / 2.; 
    if (method == 1) {
        if (length(fragCoord-mid)< iResolution.y / 2.)
            return randpix(fragCoord);
        else return liveval-1.;
    }
    if (method == 2) {
        if (fragCoord.x > mid.x - iResolution.x * 0.38 && fragCoord.x < mid.x + iResolution.x * 0.38 && fragCoord.y > mid.y - iResolution.y * 0.18 && fragCoord.y < mid.y + iResolution.y * 0.18)
            return randpix(fragCoord);
        else return liveval-1.;
    }
    return 0.;
}

vec3 ColorPalette(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.28318*(c*t+d) );
}

vec3 GetColor(float v) 
{
	return ColorPalette(v, vec3(0.5, 0.5, 0.5), 
                           vec3(0.9, 0.2, 0.8), 
                           vec3(0.6, 0.7, 0.8), 
                           vec3(0.2, 0.4, 1.0));  
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float ix = 0.;
    float xres = texelFetch(iChannel2, ivec2(0,1), 0 ).x;
    int speed = int(texelFetch(iChannel2, ivec2(2,0), 0 ).x);
    int method = int(texelFetch(iChannel2, ivec2(11,0), 0 ).x);
    int aa = int(texelFetch(iChannel2, ivec2(5,0), 0 ).x);
    float colp = texelFetch(iChannel2, ivec2(13,0), 0 ).x * 0.1*32.;


    int zoom = int(texelFetch(iChannel1, ivec2(14,0), 0 ).x);


    ivec2 px = ivec2( fragCoord );
    vec4 curr = cellval(px);
    float ev = curr.w;

    float rn = hash1(iTime+fragCoord.x*13.0+hash1(fragCoord.y*17.1));
    if (int(ev)<int(liveval-1.) && int(ev)>0 && rn < 0.0002) {
        fragColor = vec4( vec3(0.1), randpix(fragCoord));
        return;
    }

    if( iFrame==0 || readKey(KEY_SPACE) || int(xres) != int(iResolution.x) ) {
        float st = restart(fragCoord, 0);
        fragColor = vec4( vec3(0.1), st);
        return;
    }

    if( readKey(KEY_Q) || readKey(KEY_W) ) {
        float st = restart(fragCoord, method);
        fragColor = vec4( vec3(0.1), st);
        return;
    }

    if (iFrame % (speed+1) > 0) {
        fragColor = curr;
        return;
    }

    int k, O=0, E=1;

    int state = int(ev);
    int ss = state + 1;
    sstarget = ss;

    k =   cell(px+ivec2(-E,-E)) + cell(px+ivec2(O,-E)) + cell(px+ivec2(E,-E))
        + cell(px+ivec2(-E, O))                        + cell(px+ivec2(E, O))
        + cell(px+ivec2(-E, E)) + cell(px+ivec2(O, E)) + cell(px+ivec2(E, E));

    if (k > 0) {
        if (ss == int(liveval))
            state = 0;
        else
            state = ss;
    }
    float ff = float(state);

    vec3 ocol = GetColor(ff * (0.35+colp));
    if (state>int(liveval-2.) || state==0) { 
        ocol = vec3(0.);

        if (aa < 2) {
            int k2 =   cellbl(px+ivec2(-E,-E)) + cellbl(px+ivec2(O,-E)) + cellbl(px+ivec2(E,-E))
                + cellbl(px+ivec2(-E, O))                        + cellbl(px+ivec2(E, O))
                + cellbl(px+ivec2(-E, E)) + cellbl(px+ivec2(O, E)) + cellbl(px+ivec2(E, E));
            if (k2 > 5) ocol = cellval(px+ivec2(0,-E)).xyz;
            else if (zoom > 0 && k2 > 3) {
                vec4 ocol4 =   cellval(px+ivec2(-E,-E)) + cellval(px+ivec2(O,-E)) + cellval(px+ivec2(E,-E))
                + cellval(px+ivec2(-E, O))                        + cellval(px+ivec2(E, O))
                + cellval(px+ivec2(-E, E)) + cellval(px+ivec2(O, E)) + cellval(px+ivec2(E, E));
                ocol = (ocol4 / 12.0).xyz;
            }
        }
    } else {
        if (aa < 4) {
            vec4 ocol4 =   cellval(px+ivec2(-E,-E)) + cellval(px+ivec2(O,-E)) + cellval(px+ivec2(E,-E))
                + cellval(px+ivec2(-E, O))                        + cellval(px+ivec2(E, O))
                + cellval(px+ivec2(-E, E)) + cellval(px+ivec2(O, E)) + cellval(px+ivec2(E, E));
            ocol4 = ocol4 / 5.0;
            float pc = (aa == 0 || aa == 2) ? 0.0 : 0.5;
            ocol = (ocol*(1.+pc) + ocol4.xyz) / (2.+pc);
            if (ocol4.xyz == vec3(0.)) ocol=vec3(0.);
        }
    }

	//fragColor = vec4( curr.xyz*0.8+ocol*0.2, ff);
    fragColor = vec4( ocol, ff );
}

float liveval = 13.0;
int sstarget;

float hash1( float n ) {
    return fract(sin(n)*138.5453123);
}

#define readKey(key) (texelFetch( iChannel1, ivec2(key, 0), 0).x > .5)

const int KEY_SPACE = 32;
const int KEY_LEFT  = 37;
const int KEY_RIGHT = 39;
const int KEY_UP    = 38;
const int KEY_DOWN  = 40;
const int KEY_ENTER = 13;
const int KEY_0     = 48;
const int KEY_1     = 49;
const int KEY_2     = 50;
const int KEY_3     = 51;
const int KEY_4     = 52;
const int KEY_5     = 53;
const int KEY_6     = 54;
const int KEY_7     = 55;
const int KEY_8     = 56;
const int KEY_9     = 57;
const int KEY_A     = 65;
const int KEY_M     = 77;
const int KEY_Z     = 90;
const int KEY_X     = 88;
const int KEY_C     = 67;
const int KEY_V     = 86;
const int KEY_B     = 66;
const int KEY_Q     = 81;
const int KEY_W     = 87;
const int KEY_E     = 69;
const int KEY_R     = 82;
const int KEY_T     = 84;
const int KEY_G     = 71;

// Persistive Keyboard Input buffer & resolution change check

vec4 keyStep(int ix, int iy, int key, float delta, float maxval) {
    vec3 keystate = texelFetch(iChannel0, ivec2(ix,iy), 0 ).xyz;
    float kx=keystate.x;
    float ky=keystate.y;
    if( readKey(key) ) {
        if (ky == 0.) {
            kx+=1.;
            if (kx >= maxval) kx=0.;
            if (kx < 0.) kx=maxval-delta;
        }
        ky+=0.01;
        if (ky >= 1.0) ky=0.;
    }
    else {
        ky = 0.;
    }
    return vec4(kx,ky,0.,0.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int ix = int(fragCoord.x), iy = int(fragCoord.y);

    if (iy > 1) {
        fragColor = vec4(0.,0.,0.,1.0);
        return;
    }

    if (ix == 2 && iy == 0) {
        float speed = texelFetch(iChannel0, ivec2(ix,iy), 0 ).x;
        if( readKey(KEY_C)) speed = 0.;
        if( readKey(KEY_V)) speed = 1.;
        if( readKey(KEY_B)) speed = 3.;
        fragColor = vec4(speed,0.,0.,0.);
        return;
    }

    if (ix == 5 && iy == 0) {
        fragColor = keyStep(ix, iy, KEY_A, 1., 5.);
        return;
    }

    if (ix == 10 && iy == 0) {
        vec2 ppos = texelFetch(iChannel0, ivec2(ix,iy), 0 ).xy;
        float mmul = iMouse.x / iResolution.x;
        vec2 mid = iResolution.xy / 2.;

        float psp=8.;
        if( readKey(KEY_RIGHT)) ppos.x += psp;
        if( readKey(KEY_LEFT)) ppos.x -= psp;
        if( readKey(KEY_DOWN)) ppos.y -= psp;
        if( readKey(KEY_UP)) ppos.y += psp;
        ppos.x = clamp(ppos.x, -mid.x*mmul, mid.x*mmul);
        ppos.y = clamp(ppos.y, -mid.y*mmul, mid.y*mmul);

        fragColor = vec4(ppos,0.,1.);
        return;
    }


    if (ix == 0 && iy == 1) {
        fragColor = vec4(iResolution.x,0.,0.,0.);
        return;
    }

    if (ix == 11 && iy == 0) {
        float method = texelFetch(iChannel0, ivec2(ix,iy), 0 ).x;
        if( readKey(KEY_Q)) method = 1.5;
        if( readKey(KEY_W)) method = 2.5;
        fragColor = vec4(method,0.,0.,0.);
        return;
    }

    if (ix == 12 && iy == 0) {
        fragColor = keyStep(ix, iy, KEY_G, 1., 2.);
        return;
    }
    if (ix == 13 && iy == 0) {
        fragColor = keyStep(ix, iy, KEY_M, 1., 5.);
        return;
    }

    if (ix == 14 && iy == 0) {

        fragColor = keyStep(ix, iy, KEY_Z, 1., 3.);

        return;

    }




    fragColor = vec4(0.,0.,0.,1.0);
}
